ALLOWED_REGIONS = {"Lima", "Arequipa", "Cusco", "Piura"}

def result(status, code, message):
    return {"status": status, "code": code, "message": message}

def validate_edad(valor):
    if valor is None:
        return result("review", "MISSING", "Campo 'edad' ausente: envía un entero 0–120 o marca como desconocido.")
    if not isinstance(valor, int):
        return result("reject", "BAD_TYPE", f"Campo 'edad' recibió {valor!r}; se espera int.")
    if valor < 0 or valor > 120:
        return result("reject", "OUT_OF_RANGE", f"Campo 'edad'={valor} fuera de rango; usa 0–120.")
    if valor < 18:
        return result("review", "NEEDS_REVIEW", f"Campo 'edad'={valor} corresponde a menor; revisa el registro.")
    return result("accept", "OK", "edad OK")

def validate_region(valor):
    if valor is None:
        return result("review", "MISSING", "Campo 'region' ausente: completa una región o marca como desconocida.")
    if not isinstance(valor, str):
        return result("reject", "BAD_TYPE", f"Campo 'region' recibió {valor!r}; se espera str.")
    if valor not in ALLOWED_REGIONS:
        return result("review", "NOT_IN_ALLOWLIST", f"Campo 'region'={valor!r} no está en el catálogo; revisa la captura.")
    return result("accept", "OK", "region OK")

def validate_monto(valor):
    if valor is None:
        return result("review", "MISSING", "Campo 'monto_ingreso' ausente: envía un entero no negativo o marca como desconocido.")
    if not isinstance(valor, int):
        return result("reject", "BAD_TYPE", f"Campo 'monto_ingreso' recibió {valor!r}; se espera int.")
    if valor < 0:
        return result("reject", "OUT_OF_RANGE", f"Campo 'monto_ingreso'={valor} negativo; usa ≥ 0.")
    if valor > 50000:
        return result("review", "NEEDS_REVIEW", f"Campo 'monto_ingreso'={valor} supera 50000; revisa la captura.")
    return result("accept", "OK", "monto OK")

def validate_record(record):
